(function(){
  window.AP_LEARNING=window.AP_LEARNING||{};
  const M=(id,title,highYield,teaching,keyPoints,visualTitle,visualItems,mnemonic,goodToKnow,practiceConnection,prompt,options)=>({id,title,highYield,teaching,keyPoints,visual:{title:visualTitle,kind:'concept-map',items:visualItems.map(x=>({label:x[0],detail:x[1]}))},mnemonic:{title:mnemonic[0],cue:mnemonic[1],explanation:mnemonic[2]},goodToKnow,practiceConnection,activity:{prompt,options:options.map(x=>({text:x[0],correct:x[1],feedback:x[2]}))}});
  window.AP_LEARNING['lesson-11']={version:1,title:'The Brain, Cranial Nerves, Autonomic Nervous System, and Special Senses',chapter:11,duration:'90–110 minutes',
    outcomes:['Locate major brain regions and connect each with its broad function.','Explain the protection supplied by meninges, cerebrospinal fluid and cerebral circulation.','Recognize high-yield cranial-nerve functions.','Contrast sympathetic, parasympathetic and somatic control.','Trace light and sound through the eye and ear.','Use neurologic condition terms accurately without diagnosing.'],
    modules:[
      {id:'brain-regions',title:'Brain regions as a working team',summary:'Avoid “one region, one behavior” oversimplification while learning each region’s anchor job.',moments:[
        M('l11-m1','Cerebrum and lobes','The cerebral cortex supports conscious sensation, movement and higher processing.',[
          'The longitudinal fissure separates right and left cerebral hemispheres, while the corpus callosum connects them. Gyri are raised folds and sulci are shallower grooves; folding expands cortical surface area.',
          'The frontal lobe supports planning and voluntary motor control; parietal regions process somatic sensation; temporal regions contribute to hearing and memory; the occipital lobe receives and interprets visual input. These functions operate through networks rather than isolated boxes.'
        ],['Longitudinal fissure separates hemispheres.','Corpus callosum connects hemispheres.','Gyri are folds.','Occipital lobe is the visual anchor.','Cortical functions are networked.'],'Cortical anchors',[['Frontal','Plan and move'],['Parietal','Body sensation'],['Temporal','Hear and remember'],['Occipital','See']],['FPTO','Front · Parietal · Temporal · Occipital','Move front-to-back around the cortex.'],'The cerebral hemispheres are highly interconnected; “left brain/right brain personality” claims are oversimplified.','Neurologic changes can affect eating behavior or food skills, but nutrition assessment should not infer a lesion location.',
        'Which lobe is the primary visual-processing anchor?',[['Occipital',true,'Correct. Visual input is received and interpreted there.'],['Temporal',false,'Temporal regions are associated more strongly with hearing and memory.'],['Frontal',false,'Frontal regions anchor planning and motor functions.']]),
        M('l11-m2','Diencephalon, brainstem and cerebellum','Relay, homeostasis, vital pathways and movement coordination occupy different regions.',[
          'The thalamus relays much sensory information toward the cortex. The hypothalamus links neural and endocrine regulation and helps govern temperature, appetite, thirst and autonomic activity; the infundibulum connects it to the pituitary. The pineal gland secretes melatonin.',
          'Midbrain, pons and medulla form the brainstem; ascending and descending tracts pass through it, and the medulla continues as the spinal cord. The reticular formation supports arousal. The cerebellum coordinates timing, balance and complex skeletal movement rather than intellectual processes or emotions.'
        ],['Thalamus is a major relay.','Hypothalamus regulates homeostasis and pituitary control.','Infundibulum connects hypothalamus and pituitary.','Reticular formation supports arousal.','Cerebellum coordinates movement.'],'Deep-brain map',[['Thalamus','Relay'],['Hypothalamus','Homeostasis'],['Brainstem','Pathways/vital centers'],['Reticular formation','Arousal'],['Cerebellum','Coordination']],['THReC','Thalamus · Hypothalamus · Reticular · Cerebellum','Attach relay, homeostasis, arousal and coordination.'],'The medulla contains pathways linking spinal cord and higher brain regions as well as important autonomic centers.','Appetite and thirst have hypothalamic components but are also shaped by environment, learning, hormones and health.',
        'Which region coordinates complex skeletal movements as a reflex center?',[['Cerebellum',true,'Correct. It refines timing, balance and coordination.'],['Corpus callosum',false,'That connects the hemispheres.'],['Occipital lobe',false,'That processes vision.']])
      ]},
      {id:'protection-nerves',title:'Protect and connect the brain',summary:'Membranes, fluid, vessels and cranial nerves interface the brain with the body.',moments:[
        M('l11-m3','Meninges, CSF and circulation','Three membranes and circulating fluid cushion vulnerable neural tissue.',[
          'From outside inward, the meninges are dura mater, arachnoid mater and pia mater. Cerebrospinal fluid (CSF) circulates through ventricles and the subarachnoid space, providing buoyancy, cushioning and chemical stability.',
          'The brain requires continuous blood flow. An interrupted vessel can produce a cerebrovascular accident, or stroke; an aneurysm is a dilation of a vessel wall that may rupture. These are urgent medical concerns, not conditions to assess through nutrition symptoms alone.'
        ],['Dura is outermost.','Arachnoid is middle.','Pia closely follows brain surface.','CSF cushions CNS.','Stroke and aneurysm are vascular terms.'],'Protective layers',[['Dura','Tough outer'],['Arachnoid','Web-like middle'],['Subarachnoid space','CSF'],['Pia','Delicate inner']],['DAP','Dura · Arachnoid · Pia','Recall meninges from outer to inner.'],'Meningitis affects meninges; encephalitis affects brain tissue itself.','Swallowing or cognition changes after a neurologic event call for coordinated clinical and nutrition care.',
        'What is the middle meningeal layer?',[['Arachnoid mater',true,'Correct. It lies between dura and pia.'],['Pia mater',false,'Pia is the innermost layer.'],['Dura mater',false,'Dura is the outermost layer.']]),
        M('l11-m4','Cranial-nerve anchors','Learn tested functions before attempting all details at once.',[
          'Twelve pairs of cranial nerves arise from the brain. The trigeminal nerve is the largest and carries facial sensation plus chewing motor fibers. The hypoglossal nerve controls tongue movements; the vestibulocochlear nerve carries hearing and balance information.',
          'The abducens nerve is motor and moves the eyeball laterally. The optic nerve carries visual information and exits the eye at the optic disc. Cranial nerves may be sensory, motor or mixed.'
        ],['Trigeminal is the largest cranial nerve.','Hypoglossal moves tongue.','Vestibulocochlear serves hearing/balance.','Abducens moves the eye.','Optic carries vision.'],'Five tested nerves',[['V Trigeminal','Face and chewing'],['VI Abducens','Eye movement'],['VIII Vestibulocochlear','Hearing/balance'],['II Optic','Vision'],['XII Hypoglossal','Tongue']],['TAVOH','Trigeminal · Abducens · Vestibulocochlear · Optic · Hypoglossal','Use the tested anchors, then add the remaining nerves later.'],'The lacrimal gland makes tears; it is a gland, not a cranial nerve.',
        'Tongue, chewing, smell and swallowing functions can affect intake; refer new deficits and collaborate on safe strategies.',
        'Which cranial nerve controls tongue movement?',[['Hypoglossal',true,'Correct. Cranial nerve XII is motor to the tongue.'],['Trigeminal',false,'It is mainly facial sensation and chewing.'],['Vestibulocochlear',false,'It serves hearing and balance.']])
      ]},
      {id:'autonomic',title:'Automatic control without a simple on/off switch',summary:'Somatic and autonomic systems serve different effectors; sympathetic and parasympathetic outputs rebalance organs.',moments:[
        M('l11-m5','Somatic versus autonomic motor output','The effector identifies the motor branch.',[
          'Somatic motor pathways control skeletal muscle. Autonomic pathways regulate smooth muscle, cardiac muscle and glands through a two-neuron chain with a peripheral ganglion.',
          'Sympathetic output generally prepares the body for challenge; parasympathetic output supports routine, nonstressful functions such as digestion. Both divisions usually maintain some activity, so “fight or flight” and “rest and digest” are useful anchors rather than complete descriptions.'
        ],['Somatic targets skeletal muscle.','Autonomic targets smooth/cardiac muscle and glands.','ANS uses a two-neuron chain.','Sympathetic mobilizes.','Parasympathetic maintains/restores.'],'Motor branches',[['Somatic','Skeletal muscle'],['Sympathetic','Mobilizing ANS'],['Parasympathetic','Restorative ANS']],['Skeletal = somatic','Somatic starts with S, as does skeletal','Autonomic covers organs and glands.'],'The somatic system does not regulate internal organs; that function belongs mainly to autonomic motor pathways.','Stress can affect appetite and digestion, but an autonomic diagnosis cannot be made from dietary patterns.',
        'Which division predominates during many normal nonstressful digestive activities?',[['Parasympathetic',true,'Correct. It supports many routine vegetative functions.'],['Sympathetic',false,'It more often mobilizes resources during challenge.'],['Somatic',false,'Somatic pathways target skeletal muscle.']]),
        M('l11-m6','Transmitters and organ effects','Ganglionic and target synapses use different transmitter patterns.',[
          'Both autonomic divisions release acetylcholine from preganglionic neurons. Parasympathetic postganglionic neurons also typically release acetylcholine; most sympathetic postganglionic neurons release norepinephrine.',
          'Effects depend on receptor type and target organ. Sympathetic activity can increase cardiac output and redirect resources, while parasympathetic activity can promote digestive motility and secretion. The divisions are coordinated, not moral opposites.'
        ],['All preganglionic ANS neurons use ACh.','Parasympathetic target endings use ACh.','Most sympathetic target endings use norepinephrine.','Effect depends on receptor and organ.'],'Two-neuron chain',[['Preganglionic','ACh in both divisions'],['Autonomic ganglion','Second neuron begins'],['Parasympathetic target','Usually ACh'],['Sympathetic target','Usually norepinephrine']],['A-A/N','ACh first; ACh parasympathetic, NE sympathetic at targets','Track each synapse separately.'],'Exceptions exist, so transmitter patterns should be learned as common organization rather than absolute rules.',
        'Discuss stress-support habits without implying that one meal can “switch off” sympathetic activity.',
        'What transmitter do both ANS divisions use before the ganglion?',[['Acetylcholine',true,'Correct. Both preganglionic neuron types release ACh.'],['Norepinephrine',false,'That is common at sympathetic target endings.'],['Melatonin',false,'Melatonin is a pineal hormone.']])
      ]},
      {id:'vision',title:'Vision: route light to neural signal',summary:'Follow light through transparent structures to photoreceptors, then out through the optic nerve.',moments:[
        M('l11-m7','Layers and the light path','The cornea and lens focus; the retina transduces.',[
          'The sclera is the tough outer coat; its transparent anterior portion is the cornea. The vascular middle layer includes choroid, ciliary body and iris. The iris controls pupil diameter and therefore light entry. The retina is the inner photosensitive layer.',
          'Light passes through cornea, aqueous humor, pupil, lens and vitreous humor before reaching the retina. The lens changes shape for near or far focus. Neural signals leave at the optic disc, a region without photoreceptors.'
        ],['Cornea is transparent outer layer.','Iris regulates pupil diameter.','Lens focuses light.','Retina contains photoreceptors.','Optic disc is the nerve exit.'],'Light route',[['Cornea','Initial refraction'],['Pupil/iris','Light amount'],['Lens','Focus'],['Vitreous','Transmits'],['Retina','Transduces'],['Optic nerve','Carries signal']],['CPLRO','Cornea · Pupil · Lens · Retina · Optic nerve','A simplified route to reconstruct under test pressure.'],'The fovea centralis is specialized for high-acuity vision, whereas the optic disc creates a blind spot.',
        'Vision changes can alter shopping and food preparation; adapt materials while referring new visual symptoms.',
        'Which layer contains the photosensitive cells?',[['Retina',true,'Correct. Rods and cones are retinal photoreceptors.'],['Sclera',false,'The sclera is the tough outer coat.'],['Iris',false,'The iris regulates pupil diameter.']]),
        M('l11-m8','Rods and cones','Sensitivity and color discrimination trade off.',[
          'Rods are highly sensitive and support dim-light, noncolor vision. Cones require more light and support color vision and fine detail; they are densely concentrated in the fovea.',
          'Photoreceptors pass signals through retinal circuits to ganglion-cell axons, which form the optic nerve. The brain then interprets the patterned activity; the eye does not produce a finished picture on its own.'
        ],['Rods work well in dim light.','Rods do not provide color vision.','Cones support color and detail.','Cones need brighter light.','Optic nerve is formed by ganglion-cell axons.'],'Photoreceptor contrast',[['Rods','Dim, sensitive, no color'],['Cones','Bright, color, fine detail'],['Fovea','High cone density']],['Rods roam at night','Rods = low light; cones = color','Pair the functional contrasts.'],'Vitamin A is involved in visual pigment physiology, but new night-vision problems should not be assumed to be dietary deficiency.',
        'Nutrition assessment can evaluate intake while ocular evaluation identifies the cause of vision change.',
        'Which photoreceptors produce color vision?',[['Cones',true,'Correct. Cones require more light and distinguish color.'],['Rods',false,'Rods are sensitive in dim light but do not produce color vision.'],['Ganglia',false,'Ganglion cells relay output rather than detect photons.']])
      ]},
      {id:'hearing-balance',title:'Hearing, balance and neurologic vocabulary',summary:'Mechanical vibration becomes neural activity; condition names point to different tissues and mechanisms.',moments:[
        M('l11-m9','From sound wave to cochlea','Outer ear collects, middle ear transfers, inner ear transduces.',[
          'Sound waves enter the auditory canal and vibrate the tympanic membrane. The malleus, incus and stapes transmit the vibration to the oval window, creating fluid waves in the cochlea that bend sensory hair cells.',
          'Signals travel through the cochlear branch of the vestibulocochlear nerve. The semicircular ducts detect rotational movements, while vestibular structures respond to linear acceleration and head position.'
        ],['Tympanic membrane vibrates first.','Ossicles transmit vibration.','Stapes contacts oval window.','Cochlear hair cells transduce sound.','Vestibular apparatus supports balance.'],'Sound pathway',[['Canal','Directs sound'],['Tympanic membrane','Vibrates'],['Ossicles','Amplify/transfer'],['Oval window','Starts inner-ear wave'],['Cochlea','Transduces'],['CN VIII','Carries signal']],['TM-O-C','Tympanic membrane · Ossicles · Cochlea','Use the three main stages, then add details.'],'The auditory tube helps equalize middle-ear pressure; it is not the main sound receptor.',
        'Hearing or balance barriers may affect counselling format and food-safety tasks; accommodate and refer appropriately.',
        'What structure first vibrates when sound reaches the end of the ear canal?',[['Tympanic membrane',true,'Correct. It transfers sound energy to the ossicles.'],['Oval window',false,'The stapes reaches it after the ossicles move.'],['Retina',false,'That is part of the eye.']]),
        M('l11-m10','Keep neurologic terms distinct','Tissue, mechanism and clinical course determine the label.',[
          'Meningitis is inflammation of the meninges; encephalitis is inflammation of brain tissue. Multiple sclerosis involves progressive demyelination in the CNS. Alzheimer disease produces progressive cognitive deterioration, while Parkinson disease is associated with movement-control circuitry.',
          'A stroke results from interrupted or bleeding cerebral circulation; an aneurysm is an abnormal vessel-wall dilation. Epilepsy involves recurrent seizure tendency. These summaries support vocabulary only—diagnosis requires clinical evaluation.'
        ],['Meningitis affects meninges.','Encephalitis affects brain tissue.','Multiple sclerosis involves CNS demyelination.','Stroke is a vascular brain event.','Aneurysm is vessel-wall dilation.'],'Term sorter',[['Membranes','Meningitis'],['Brain tissue inflammation','Encephalitis'],['Myelin','Multiple sclerosis'],['Blood flow','Stroke'],['Vessel wall','Aneurysm']],['ME-MSA','Meningitis · Encephalitis · MS · Stroke · Aneurysm','Attach each term to its primary tissue/mechanism.'],'Similar symptoms can arise from very different processes, which is why pattern-matching is unsafe.',
        'Neurologic conditions may change energy needs, swallowing or self-management; nutrition care should be coordinated with the clinical team.',
        'Which term means inflammation of brain tissue?',[['Encephalitis',true,'Correct. Encephalo- refers to brain.'],['Meningitis',false,'That affects the meninges.'],['Aneurysm',false,'That is vessel-wall dilation.']])
      ]}
    ],
    caseStudy:{title:'One breakfast, many neural tasks',scenario:'An older adult after a clinician-diagnosed stroke has visual-field difficulty, reduced hand control and trouble following a fast conversation.',prompts:['Name the broad brain and sensory systems involved without localizing the lesion.','Identify accommodations that could make counselling accessible.','Explain the roles of cranial nerves and somatic motor pathways in eating.','List issues that require team-based assessment, such as swallowing safety.'],takeaway:'Anatomy helps anticipate functional demands and design access; it does not replace neurologic or swallowing assessment.'},
    recap:['Cerebral lobes have useful anchor functions but work as networks.','Thalamus relays; hypothalamus regulates homeostasis; cerebellum coordinates.','Dura, arachnoid and pia protect the CNS with CSF cushioning.','Cranial nerves carry sensory, motor or mixed information.','Somatic pathways target skeletal muscle; autonomic pathways serve organs and glands.','The retina transduces light; rods favor dim light and cones color/detail.','The tympanic membrane, ossicles and cochlea convert sound to neural signals.'],
    flashcards:[{front:'Longitudinal fissure',back:'Deep groove separating the cerebral hemispheres.',tag:'brain'},{front:'Gyri',back:'Raised folds of the cerebral cortex.',tag:'brain'},{front:'Cerebellum',back:'Region coordinating balance and complex skeletal movement.',tag:'brain'},{front:'Reticular formation',back:'Brainstem network involved in arousal and consciousness.',tag:'brain'},{front:'Arachnoid mater',back:'Middle meningeal layer.',tag:'protection'},{front:'Cerebrospinal fluid',back:'Fluid that cushions and supports the CNS.',tag:'protection'},{front:'Trigeminal nerve',back:'Largest cranial nerve; facial sensation and chewing functions.',tag:'cranial nerve'},{front:'Hypoglossal nerve',back:'Motor nerve controlling tongue movement.',tag:'cranial nerve'},{front:'Retina',back:'Innermost eye layer containing photoreceptors.',tag:'vision'},{front:'Cones',back:'Photoreceptors for color and fine detail in brighter light.',tag:'vision'},{front:'Tympanic membrane',back:'Membrane vibrated by incoming sound waves.',tag:'hearing'},{front:'Encephalitis',back:'Inflammation of brain tissue.',tag:'condition'},{front:'Stroke',back:'Brain injury from interrupted or bleeding cerebral circulation.',tag:'condition'},{front:'Aneurysm',back:'Abnormal dilation of a blood-vessel wall.',tag:'condition'}],
    practice:[{prompt:'What separates and what connects the cerebral hemispheres?',answer:'The longitudinal fissure separates them; the corpus callosum connects them.',rationale:'The structures have opposite organizational roles.',tag:'brain'},{prompt:'Which lobe receives visual input?',answer:'Occipital lobe.',rationale:'It is the main cortical visual anchor.',tag:'brain'},{prompt:'Name the meninges outside to inside.',answer:'Dura, arachnoid, pia.',rationale:'This order also locates the CSF-filled subarachnoid space.',tag:'protection'},{prompt:'Which structure connects hypothalamus to pituitary?',answer:'Infundibulum.',rationale:'It is the physical stalk between them.',tag:'brain'},{prompt:'Match trigeminal, abducens and hypoglossal with an anchor function.',answer:'Facial sensation/chewing; eye movement; tongue movement.',rationale:'These functions cover the supplied quiz emphasis.',tag:'cranial nerve'},{prompt:'Contrast somatic and autonomic motor systems.',answer:'Somatic controls skeletal muscle; autonomic regulates smooth/cardiac muscle and glands.',rationale:'The effector defines the branch.',tag:'ANS'},{prompt:'Trace light from cornea to optic nerve.',answer:'Cornea → pupil → lens → vitreous → retina → optic nerve.',rationale:'This follows focusing, transduction and output.',tag:'vision'},{prompt:'Contrast rods and cones.',answer:'Rods are sensitive in dim light without color; cones need more light and provide color/detail.',rationale:'Sensitivity and resolution differ.',tag:'vision'},{prompt:'Trace sound to neural transduction.',answer:'Canal → tympanic membrane → ossicles → oval window → cochlear hair cells → CN VIII.',rationale:'Mechanical energy becomes a neural signal in the cochlea.',tag:'hearing'},{prompt:'Distinguish meningitis, encephalitis and multiple sclerosis.',answer:'Meninges inflammation, brain-tissue inflammation, and CNS demyelination.',rationale:'Each term centers on a different structure or process.',tag:'condition'}]
  };
})();
